p_grid = np.linspace(0.001, 0.999, 999)

def bernoulli_loglik(p, k, n):
    return k * np.log(p) + (n - k) * np.log(1 - p)

for k, n in [(7, 10), (70, 100)]:
    ll = bernoulli_loglik(p_grid, k, n)
